8. namespace sv_01ccf5cce9bb4f259b8616ecd25e6a4e;
9. 
10. /// <summary>
11. /// Serializes the server-side authentication state into PersistentComponentState
12. /// so the WebAssembly client can reconstruct the user's identity after taking over.
13. /// </summary>
14. public class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
15. {
16.     private readonly PersistentComponentState _persistentState;
17.     private readonly PersistingComponentStateSubscription _subscription;
18.     private Task<AuthenticationState>? _authStateTask;
19. 
20.     public PersistingAuthenticationStateProvider(PersistentComponentState persistentState)
21.     {
22.         _persistentState = persistentState;
23.         _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, new InteractiveWebAssemblyRenderMode());
24. 
25.         var claims = new[]
26.         {
27.             new Claim(ClaimTypes.Name, "bob@example.com"),
28.             new Claim(ClaimTypes.Email, "bob@example.com"),
29.             new Claim(ClaimTypes.Role, "User"),
30.             new Claim(ClaimTypes.Role, "Editor"),
31.         };
32.         var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
33.         _authStateTask = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
34.     }
35. 
36.     public override Task<AuthenticationState> GetAuthenticationStateAsync()
37.         => _authStateTask!;
38. 
39.     private async Task OnPersistingAsync()
40.     {
41.         var state = await GetAuthenticationStateAsync();
42.         var user = state.User;
43. 
44.         if (user.Identity?.IsAuthenticated == true)
45.         {
46.             _persistentState.PersistAsJson("UserInfo", new UserInfo
47.             {
48.                 Name = user.Identity.Name!,
49.                 Roles = user.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
50.             });
51.         }
52.     }
53. 
54.     public void Dispose() => _subscription.Dispose();
55. }
56.

